if L=="frFR" then -- fr
    plain={
        ["  All stocked up."]="  Tout est en stock.",
        ["[+] done. [=] in your log. Click one for an arrow to its giver."]="[+] faite. [=] dans ton journal. Clique sur une pour une fl\195\168che vers son donneur.",
        ["/bf access - marks that do not rely on colour, and larger text in the Compass and settings window"]="/bf access - des marques qui ne d\195\169pendent pas de la couleur, et un texte plus grand dans la Boussole et la fen\195\170tre de r\195\169glages",
        ["/bf addons - other addons found and what Backstage Forever switched off beside them (on or off)"]="/bf addons - les autres addons trouv\195\169s et ce que Backstage Forever a coup\195\169 \195\160 c\195\180t\195\169 d'eux (on ou off)",
