        {"^Your gear has lost (%-?%d+)%% of its durability%. Most worn first:$","Ton \195\169quipement a perdu %1%% de sa durabilit\195\169. Le plus us\195\169 d'abord\194\160:"},
        {"^(%-?%d+) letters expire within 3 days%. The soonest has (.-) left%.$","%1 lettres expirent dans les 3 jours. Il reste %2 \195\160 la plus proche."},
        {"^Weapon skills, lowest first%. The cap at level (%-?%d+) is (%-?%d+)%.$","Comp\195\169tences d'arme, les plus basses d'abord. Le plafond au niveau %1 est %2."},
